from auto_config.generator.vcu.managed_objects.managed_object import ManagedObject


class NrduParamsGenerator(ManagedObject):

    def _prepare_section_content(self, execution_config, *args, **kwargs):
        du_ent = self.enb_ent_config['dus'][self.mo_num]
        gnb_du_id = du_ent['gnb_du_id'] if 'gnb_du_id' in du_ent else self.mo_num

        self.set_parameter('gNbDuId', gnb_du_id)
        self.set_parameter('remoteDuIpAddr', du_ent['ip_addr'])
        self.set_parameter('refNrCellGroup', du_ent['cell_group'])

        if self.is_sa:
            self.set_parameter('numOfDrbsReservForEmergency', '0')
